import java.util.Scanner;

public class Main {
    static long[] f = new long[181];
    static long n;
    static long ans;

    static long Abs(long a) {
        return a < 0 ? -a : a;
    }

    static void recurse(int level, long total_cost) {
        if (n == 0) {
            ans = Math.min(ans, total_cost);
            return;
        }
        if (level == 0) return;

        for (int i = -10; i <= 10; ++i) {
            long delta = i * f[level];
            if (n + delta > 0) {
                n += delta;
                recurse(level - 1, total_cost + Abs(i) * level);
                n -= delta;
                break;
            }
        }
        for (int i = -10; i <= 10; ++i) {
            long delta = i * f[level];
            if (n + delta == 0) {
                n += delta;
                recurse(level - 1, total_cost + Abs(i) * level);
                n -= delta;
                break;
            }
        }
        for (int i = 10; i >= -10; --i) {
            long delta = i * f[level];
            if (n + delta < 0) {
                n += delta;
                recurse(level - 1, total_cost + Abs(i) * level);
                n -= delta;
                break;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        f[1] = 1;
        for (int i = 2; i <= 16; ++i) {
            f[i] = f[i - 1] * 10 + 1;
        }
        ans = Long.MAX_VALUE;
        recurse(16, 0);
        System.out.println(ans);
        sc.close();
    }
